import type { Company } from '@cala/contracts';
import { createRepositoriesFromEnv, createInMemoryRepositories, createInMemoryStore, type Repositories } from '@cala/db';
import { createGraphFromEnv, type GraphProjector } from '@cala/graph';
import { HttpCalaClient, type CalaClient } from './cala.js';
import { OpenAIFastinoClient, type FastinoClient } from './fastino.js';
import { createOpenAIClient, type OpenAIClient } from './models.js';
import { defaultResearchTools, type ResearchTool } from './tools.js';

export type WorkflowDeps = {
  cala: CalaClient;
  fastino: FastinoClient;
  repos: Repositories;
  graph: GraphProjector;
  tools: ResearchTool[];
  openai?: OpenAIClient;
};

function createSeededStore(companies: Company[]) {
  return createInMemoryStore({ companies });
}

// Production wiring from environment. Requires OPENAI_API_KEY; Cala/Neo4j fall
// back to mock/in-memory when their env is unset.
export function defaultDeps(seed?: { companies?: Company[] }): WorkflowDeps {
  const openai = createOpenAIClient();
  const repos = seed?.companies
    ? createInMemoryRepositories(createSeededStore(seed.companies))
    : createRepositoriesFromEnv();
  return {
    openai,
    cala: new HttpCalaClient(),
    fastino: new OpenAIFastinoClient(openai.chat),
    repos,
    graph: createGraphFromEnv(),
    tools: defaultResearchTools(),
  };
}

import { Router } from 'express';
import { createRepositoriesFromEnv } from '@cala/db';

const repos = createRepositoriesFromEnv();
export const companiesRouter = Router();
companiesRouter.get('/', async (_req, res) => res.json(await repos.companies.list()));
companiesRouter.post('/', async (req, res) => {
  const { name, ticker = null } = req.body ?? {};
  if (typeof name !== 'string' || !name.trim() || (ticker !== null && typeof ticker !== 'string')) {
    return res.status(400).json({ error: 'name and ticker are required' });
  }
  return res.status(201).json(await repos.companies.create({ name: name.trim(), ticker }));
});

import { Router } from 'express';
import { createRepositoriesFromEnv } from '@cala/db';

const repos = createRepositoriesFromEnv();
export const runsRouter = Router();
export let enqueueRun = (_runId: string): void => {};
export function setEnqueueRun(fn: (runId: string) => void): void {
  enqueueRun = fn;
}
runsRouter.post('/', async (req, res) => {
  const { companyId, mode } = req.body ?? {};
  if (mode !== 'seed' && mode !== 'delta') return res.status(400).json({ error: "mode must be 'seed' or 'delta'" });
  const run = await repos.runs.create({ companyId, mode });
  enqueueRun(run.id);
  return res.status(202).json({ id: run.id, status: 'queued' });
});
runsRouter.get('/:id', async (req, res) => {
  const run = await repos.runs.get(req.params.id);
  return run ? res.json(run) : res.status(404).json({ error: 'run not found' });
});

import request from 'supertest';
import { beforeEach, describe, expect, it } from 'vitest';
import { app } from '../app.js';
import { resetRepositoriesForTests } from '@cala/db';

beforeEach(() => resetRepositoriesForTests());

describe('companies API', () => {
  it('returns companies ordered by display order then name', async () => {
    await request(app).post('/companies').send({ name: 'Zulu', ticker: null });
    await request(app).post('/companies').send({ name: 'Alpha', ticker: null });
    const response = await request(app).get('/companies');
    expect(response.status).toBe(200);
    expect(response.body.map((c: { name: string }) => c.name)).toEqual(['Zulu', 'Alpha']);
  });
