`.trim();

const WRITE_PATTERN = /\b(insert|update|delete|drop|alter|truncate|create|grant|revoke|copy|call|execute|do|comment|security|set\s+role|load|import)\b/i;

export function assertReadOnlySelect(sql: string): string {
  const stripped = sql.replace(/\/\*[\s\S]*?\*\//g, ' ').replace(/--.*$/gm, ' ').trim();
  if (!stripped) throw new Error('SQL query is empty');
  if (stripped.replace(/;\s*$/, '').includes(';')) throw new Error('Only a single SELECT statement is allowed');
  const normalized = stripped.replace(/;\s*$/, '').trim();
  if (!/^(select|with)\b/i.test(normalized)) throw new Error('Only read-only SELECT queries are allowed');
  if (WRITE_PATTERN.test(normalized)) throw new Error('Write or administrative SQL is not allowed');
  return normalized;
}

export type GeneratedSql = { sql: string; explanation: string };

function parseSqlResponse(raw: string): GeneratedSql {
  try {
    const parsed = JSON.parse(raw) as Partial<GeneratedSql>;
    if (parsed.sql) return { sql: parsed.sql, explanation: parsed.explanation ?? '' };
  } catch {
    const fenced = raw.match(/```sql\s*([\s\S]*?)```/i);
    if (fenced?.[1]) return { sql: fenced[1].trim(), explanation: raw.replace(fenced[0], '').trim() };
  }
  throw new Error('The SQL agent did not return a query');
}

export async function generateSqlQuery(chat: ChatModel, question: string): Promise<GeneratedSql> {
  const raw = await chat.complete({
    system: `You write PostgreSQL for a healthcare market-intelligence database. Return JSON { "sql": string, "explanation": string }.
Rules:
- One read-only SELECT or WITH ... SELECT.
- Never modify data.
- Prefer LIMIT 100 unless the user asks for more, capped at 200.
- Use the schema exactly; quote identifiers only when needed.
- Join companies to source_documents and entities when the question is about a company.
Schema:
${SQL_SCHEMA}`,
    user: question,
    jsonSchema: {
      name: 'sql_query',
      schema: {
        type: 'object',
        additionalProperties: false,
        properties: {
          sql: { type: 'string' },
          explanation: { type: 'string' },
        },
        required: ['sql', 'explanation'],
      },
    },
  });
  const generated = parseSqlResponse(raw);
  return { sql: assertReadOnlySelect(generated.sql), explanation: generated.explanation };
}

import { describe, expect, it } from 'vitest';
import { StubChatModel } from './models.js';
import { assertReadOnlySelect, generateSqlQuery } from './sql.js';

describe('assertReadOnlySelect', () => {
  it('accepts a select and strips a trailing semicolon', () => {
    expect(assertReadOnlySelect('SELECT id, name FROM companies;')).toBe('SELECT id, name FROM companies');
  });

  it('rejects writes and stacked statements', () => {
    expect(() => assertReadOnlySelect('DELETE FROM companies')).toThrow(/read-only/i);
    expect(() => assertReadOnlySelect('SELECT 1; DROP TABLE companies')).toThrow(/single SELECT/i);
  });
});

describe('generateSqlQuery', () => {
  it('asks the model and validates the returned SQL', async () => {
    const chat = new StubChatModel(() => JSON.stringify({
      sql: 'SELECT name, ticker FROM companies ORDER BY display_order LIMIT 20',
      explanation: 'List watchlist companies.',
    }));
    const result = await generateSqlQuery(chat, 'show all companies');
    expect(result.sql).toMatch(/^SELECT name, ticker FROM companies/i);
    expect(result.explanation).toContain('watchlist');
    expect(chat.calls[0]?.user).toBe('show all companies');
  });
});

import { assertReadOnlySelect } from '@cala/agents';
import { pool } from './client.js';

const MAX_ROWS = 200;

export type SqlQueryResult = { rows: Record<string, unknown>[]; rowCount: number };

export async function executeReadOnlySql(sql: string): Promise<SqlQueryResult> {
  const safe = assertReadOnlySelect(sql);
  const client = await pool.connect();
  try {
    await client.query('BEGIN READ ONLY');
    await client.query("SET LOCAL statement_timeout = '8000'");
    const result = await client.query(safe);
    await client.query('COMMIT');
    const rows = (result.rows as Record<string, unknown>[]).slice(0, MAX_ROWS);
    return { rows, rowCount: rows.length };
  } catch (error) {
    await client.query('ROLLBACK').catch(() => undefined);
    throw error;
  } finally {
    client.release();
  }
}

