    sql: MODERNA_SQL,
    graphFilter: {
      companyTicker: 'MRNA',
      companyName: 'Moderna',
      entityTypes: ['company', 'clinical_trial', 'paper', 'news'],
      relationshipTypes: ['TRIAL_BY', 'RESEARCH_ON', 'REPORTED_ON'],
    },
